test('invoiceTotals sums line totals with VAT', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'STICKER', name: 'Sticker sheet', qty: 5, unitPrice: 50, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000 + 250);
  assert.equal(totals.discount, 0);
  // VAT: (85000 + 250) * 0.21 = 85250 * 0.21 = 17902.5 → 17902 (banker's rounding, rounds to even)
  assert.equal(totals.vat, 17902);
  assert.equal(totals.total, 85250 + 17902);
});

